const lake=globalThis.DreamLake?.create({container:$('#lake-view'),getState:()=>({scene,hidden:ceremony.hidden||releaseMode!=='water',gentle:gentleMotion}),onRelease:()=>launchWish(),onHint:text=>{$('#ceremony-hint').textContent=text}});
// The sky after the lake stays calm; the interactive reply owns its own imagery.
(()=>{const layer=$('#atmosphere'),g=layer.getContext('2d');let w=0,h=0;const stars=Array.from({length:100},()=>({x:Math.random(),y:Math.random(),r:.25+Math.random(),phase:Math.random()*6}));function frame(t){requestAnimationFrame(frame);lake?.update(t);if(ceremony.hidden)return;const active=!['packing','ready','flying','witnessing'].includes(scene);if(!active){g.clearRect(0,0,w,h);return}if(w!==innerWidth||h!==innerHeight){w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,1.5);layer.width=w*d;layer.height=h*d;layer.style.width=w+'px';layer.style.height=h+'px';g.setTransform(d,0,0,d,0,0)}g.clearRect(0,0,w,h);for(const star of stars){g.globalAlpha=.18+(Math.sin((gentleMotion?0:t*.0005)+star.phase)+1)*.16;g.fillStyle='#e8dbbd';g.beginPath();g.arc(star.x*w,star.y*h,star.r,0,7);g.fill()}g.globalAlpha=1;const witness=$('.witness');if(witness&&scene!=='witnessing'){witness.style.left='';witness.style.top=''}}requestAnimationFrame(frame)})();
let waterNoise=null,waterVolume=null;
function waterAmbience(active){if(active&&sound&&!waterNoise){try{audio??=new(window.AudioContext||window.webkitAudioContext)();const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate),data=buffer.getChannelData(0);let value=0;for(let i=0;i<data.length;i++){value=(value+(Math.random()*2-1)*.02)/1.02;data[i]=value*3*(.7+.3*Math.sin(i/audio.sampleRate*2))}const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();source.buffer=buffer;source.loop=true;filter.type='lowpass';filter.frequency.value=550;gain.gain.setValueAtTime(0,audio.currentTime);gain.gain.linearRampToValueAtTime(.09,audio.currentTime+2);source.connect(filter);filter.connect(gain);gain.connect(audio.destination);source.start();waterNoise=source;waterVolume=gain}catch{}}else if((!active||!sound)&&waterNoise){waterVolume.gain.setTargetAtTime(0,audio.currentTime,.35);waterNoise.stop(audio.currentTime+1);waterNoise=null}}
(()=>{function frame(){requestAnimationFrame(frame);waterAmbience(releaseMode==='water'&&!ceremony.hidden&&['ready','flying','packing'].includes(scene))}requestAnimationFrame(frame)})();
